const strToInt = (s) => {
	const n = parseInt(s);
	return Number.isNaN(n) ? 0 : n;
}

const strToNum = (s) => {
	s = s.replace( ',', '.' );
	return parseFloat( s );
	// const n = parseFloat( s );
	// return isNaN(n) ? 0 : n;
}

