class ResolvablePromise {

	constructor() {
		this.prom = new Promise( (res,rej) => {
			this.res = res;
			this.rej = rej;
		});
	}

	resolvePromise( res ) {
		this.res( res );
	}

	rejectPromise( rej ) {
		this.rej( rej );
	}

	get promise() {
		return this.prom;
	}
}

